TypeScript example - async iterator + tool call correlation:

import { RedwoodClient, EventKind } from 'redwood-sdk';

const client = new RedwoodClient({ apiKey: process.env.RW_KEY });

async function run() {
  // Start a sessioned invocation that emits structured events
  const resp = await client.invoke({ model: 'gpt-x', inputs: 'Summarize and call tools', session: { ttlSeconds: 120 } });

  // resp.stream is an async iterator over event envelopes
  for await (const ev of resp.stream) {
    if (ev.kind === EventKind.PartialJson) {
      // incremental partial JSON fragment (append-safe)
      processPartial(ev.payload);
    } else if (ev.kind === EventKind.ToolCall) {
      // engine asked to call a tool; correlation via ev.tool_id and ev.call_id
      const toolResult = await callLocalTool(ev.tool_id, ev.args);
      // send tool result back associated with same session & call_id
      await client.toolResponse({ session_id: resp.session_id, call_id: ev.call_id, result: toolResult });
    } else if (ev.kind === EventKind.FinalJson) {
      finalize(JSON.parse(ev.payload));
    }
  }
}

run().catch(console.error);

Go example - channel-based streaming + backpressure control:

package main

import (
  "context"
  rw "github.com/redwood-inference/go-sdk"
)

func main() {
  client := rw.NewClient("$RW_KEY")
  ctx := context.Background()
  res, _ := client.Invoke(ctx, rw.InvokeParams{Model: "gpt-x", Inputs: "Plan with tool calls", SessionTTL: 120})
  // res.Stream is implemented as a read-only channel of Event envelopes
  for ev := range res.Stream {
    switch ev.Kind {
    case rw.EventPartialJSON:
      handlePartial(ev.Payload)
    case rw.EventToolCall:
      // run tool; ensure we don't block serving runtime by making tool calls on a dedicated worker pool
      go func(call rw.ToolCall) {
        result := runTool(call.ToolID, call.Args)
        client.ToolResponse(ctx, res.SessionID, call.CallID, result)
      }(ev.ToolCall)
    case rw.EventFinalJSON:
      finalize(ev.Payload)
    }
  }
}

// Note: Go example shows callers must manage concurrency to avoid blocking the stream reader.

Backward-compatibility shim (pseudo):

// legacyCallback is old SDK: onTextDelta(delta)
function compatSubscribe(resp, legacyCallback) {
  // convert progressive partial_json events to text deltas for legacy users
  (async () => {
    for await (const ev of resp.stream) {
      if (ev.kind === EventKind.PartialJson) {
        // map envelope to text delta; best-effort flattening
        legacyCallback(ev.payload_text_delta || flattenJsonPartial(ev.payload));
      }
      // ignore tool_call events for legacy clients or expose a simple 'tool_request' callback
      if (ev.kind === EventKind.ToolCall && typeof legacyCallback.onToolRequest === 'function') {
        legacyCallback.onToolRequest(ev.tool_id, ev.args);
      }
    }
  })();
}
